[UnityTest] public IEnumerator H01_ExistingWindowsPlayerStarts(){
 string exe=System.IO.Path.GetFullPath("Builds/Windows-Validated/DHARA.exe");Assert.That(System.IO.File.Exists(exe),Is.True);
 string log=System.IO.Path.GetFullPath("Verification/exploration-H01-player.log");
 var process=System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(exe,"-screen-fullscreen 0 -screen-width 1280 -screen-height 800 -logFile "+log){UseShellExecute=false});
 try{float end=Time.realtimeSinceStartup+25;while(Time.realtimeSinceStartup<end&&!process.HasExited){process.Refresh();if(process.MainWindowHandle!=IntPtr.Zero&&System.IO.File.Exists(log)&&ReadShared(log).Contains("UnloadTime:"))break;yield return null;}
 process.Refresh();Assert.That(process.HasExited,Is.False);Assert.That(process.MainWindowHandle,Is.Not.EqualTo(IntPtr.Zero));string probePath=System.IO.Path.GetFullPath("Verification/exploration-H01-probe.json");
 var probe=System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo("C:/Users/Roshan/.cache/codex-runtimes/codex-primary-runtime/dependencies/native/powershell/pwsh.exe","-NoProfile -File Tools/Probe-Standalone.ps1 -PlayerId "+process.Id+" -OutputPath "+probePath){UseShellExecute=false,CreateNoWindow=true});
 float probeEnd=Time.realtimeSinceStartup+10;while(!probe.HasExited&&Time.realtimeSinceStartup<probeEnd)yield return null;
 Assert.That(probe.HasExited,Is.True);Assert.That(probe.ExitCode,Is.Zero);var readiness=JsonUtility.FromJson<PlayerProbe>(System.IO.File.ReadAllText(probePath));Assert.That(readiness.responding&&readiness.hasWindow,Is.True);probe.Dispose();Assert.That(ReadShared(log),Does.Not.Contain("NullReferenceException"));}
 finally{if(!process.HasExited)process.CloseMainWindow();process.Dispose();}}

[Test] public void S32_HeavyRainCannotEnableObscuringBloom(){Draw(200,180,150,1);var volume=app.World.GetComponentInChildren<UnityEngine.Rendering.Volume>();UnityEngine.Rendering.Universal.Bloom bloom;Assert.That(volume.sharedProfile.TryGet(out bloom),Is.True);Assert.That(bloom.active,Is.True);Assert.That(bloom.intensity.overrideState,Is.True);Assert.That(bloom.intensity.value,Is.Zero);
var manager=UnityEngine.Rendering.VolumeManager.instance;bool owned=!manager.isInitialized;
UnityEngine.Rendering.VolumeProfile defaults=null;
if(owned){defaults=ScriptableObject.CreateInstance<UnityEngine.Rendering.VolumeProfile>();defaults.Add<UnityEngine.Rendering.Universal.Bloom>(true).intensity.Override(.25f);manager.Initialize(defaults);}
var stack=manager.CreateStack();
try{manager.Update(stack,app.World.ViewCamera.transform,1<<volume.gameObject.layer);var effective=stack.GetComponent<UnityEngine.Rendering.Universal.Bloom>();Assert.That(effective,Is.Not.Null);Assert.That(effective.intensity.value,Is.Zero);}finally{manager.DestroyStack(stack);if(owned){manager.Deinitialize();Object.Destroy(defaults);}}}
